export type FlightTrackerCardProps = Record<string, any>;

const FlightTrackerCard: React.FC<FlightTrackerCardProps> = ({
  backgroundColor = "#e0e0e0",
  transparentBackground = true,
  durationInSeconds = 8,
  departureCode = "YYZ",
  arrivalCode = "HND",
  departureCity = "Toronto",
  arrivalCity = "Tokyo",
  departureTime = "MON, 6:14 PM",
  arrivalTime = "TUE, 7:14 AM",
  etaText = "ETA 2:15 PM",
  statusText = "DINNER IN 2:34H",
  progress = 65,
  primaryColor = "#7cff01", // Bright green
  secondaryColor = "#ff7b00", // Orange
  cardColor = "#0f0f12", // Dark card
}) => {
  useFontLoader(["Codystar", "Inter", "Roboto"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Constants ---
  const entranceDuration = 30;
  
  // Card Entrance
  const cardScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80, mass: 1.2 },
  });

  const cardOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Text Stagger
  const textOpacity = interpolate(frame, [15, 45], [0, 1], {
    extrapolateRight: "clamp",
  });

  const textTranslateY = interpolate(frame, [15, 45], [20, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateRight: "clamp",
  });

  // Blinking Effect for Arrival Code
  // Creates a pulsing opacity between 0.4 and 1.0
  const blinkValue = interpolate(
    Math.sin(frame / 8),
    [-1, 1],
    [0.4, 1]
  );
  // Combine blinking with the entrance opacity
  const arrivalTextOpacity = textOpacity * blinkValue;

  // Progress Bar Animation
  const progressValue = spring({
    frame: frame - 25,
    fps,
    config: { damping: 20, stiffness: 60 },
  });
  
  const currentProgress = interpolate(
    progressValue,
    [0, 1],
    [0, progress],
    { extrapolateRight: "clamp" }
  );

  // Status Panel Animation
  const panelSlide = spring({
    frame: frame - 40,
    fps,
    config: { damping: 15, stiffness: 100 },
  });
  
  const panelX = interpolate(panelSlide, [0, 1], [50, 0], {
     extrapolateRight: "clamp",
  });
  
  const panelOpacity = interpolate(frame, [40, 60], [0, 1], {
    extrapolateRight: "clamp",
  });

  // --- Styles ---
  
  // Increased card height slightly to provide more vertical breathing room
  const cardWidth = width * 0.65;
  const cardHeight = height * 0.50; // Increased from 0.45 to 0.50 for spacing
  const borderRadius = 32;
  const padding = cardWidth * 0.08;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Main Card */}
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          backgroundColor: cardColor,
          borderRadius: borderRadius,
          transform: `scale(${cardScale})`,
          opacity: cardOpacity,
          position: "relative",
          boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          padding: `${padding}px`,
          color: "white",
          gap: 20, // Add gap to ensure elements don't touch
        }}
      >
        {/* Top Section: Flight Codes & Status */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", width: "100%" }}>
          
          {/* Flight Info Left */}
          <div style={{ display: "flex", gap: "2rem", alignItems: "center" }}>
            {/* Departure */}
            <div>
              <h1
                style={{
                  fontFamily: "Codystar, monospace",
                  fontWeight: 700,
                  fontSize: cardWidth * 0.09,
                  lineHeight: 1,
                  margin: 0,
                  color: "#ffffff",
                  opacity: textOpacity,
                  transform: `translateY(${textTranslateY}px)`,
                  letterSpacing: "0.05em",
                }}
              >
                {departureCode}
              </h1>
              <div
                style={{
                  marginTop: 15,
                  opacity: textOpacity,
                  transform: `translateY(${textTranslateY}px)`,
                }}
              >
                <div style={{ fontSize: cardWidth * 0.025, fontWeight: 600 }}>
                  {departureCity}
                </div>
                <div style={{ fontSize: cardWidth * 0.018, color: "#888", marginTop: 4, fontWeight: 500 }}>
                  {departureTime}
                </div>
              </div>
            </div>

            {/* Arrow */}
            <div style={{ 
                opacity: textOpacity, 
                transform: `translateY(${textTranslateY - 10}px)`,
                paddingBottom: 40 // Align with large text visual center
            }}>
              <ArrowRightIcon color={secondaryColor} size={cardWidth * 0.04} />
            </div>

            {/* Arrival (With Blinking Effect) */}
            <div>
              <h1
                style={{
                  fontFamily: "Codystar, monospace",
                  fontWeight: 700,
                  fontSize: cardWidth * 0.09,
                  lineHeight: 1,
                  margin: 0,
                  color: primaryColor,
                  opacity: arrivalTextOpacity, // Applying blink effect here
                  transform: `translateY(${textTranslateY}px)`,
                  textShadow: `0 0 20px ${primaryColor}66`,
                  letterSpacing: "0.05em",
                }}
              >
                {arrivalCode}
              </h1>
              <div
                style={{
                  marginTop: 15,
                  opacity: textOpacity,
                  transform: `translateY(${textTranslateY}px)`,
                }}
              >
                <div style={{ fontSize: cardWidth * 0.025, fontWeight: 600 }}>
                  {arrivalCity}
                </div>
                <div style={{ fontSize: cardWidth * 0.018, color: "#888", marginTop: 4, fontWeight: 500 }}>
                  {arrivalTime}
                </div>
              </div>
            </div>
          </div>

          {/* Status Panel (Top Right) */}
          <div
            style={{
              backgroundColor: "#1a1a1e",
              padding: "20px 24px",
              borderRadius: 16,
              opacity: panelOpacity,
              transform: `translateX(${panelX}px)`,
              display: "flex",
              flexDirection: "column",
              gap: 8,
              minWidth: cardWidth * 0.25,
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontSize: cardWidth * 0.022, fontWeight: 700, color: "white" }}>
                {etaText}
              </span>
              <DoubleArrowIcon color="#666" size={16} />
            </div>
            <span style={{ fontSize: cardWidth * 0.018, color: "#666" }}>
              {arrivalCity} Time
            </span>
            <span style={{ fontSize: cardWidth * 0.018, color: secondaryColor, fontWeight: 700, marginTop: 4 }}>
              {statusText}
            </span>
          </div>
        </div>

        {/* Bottom Section: Progress Bar */}
        {/* Added extra top padding to push it down further as requested */}
        <div style={{ position: "relative", width: "100%", marginTop: "auto", paddingTop: cardWidth * 0.02 }}>
            
          {/* Progress Container */}
          <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
            <div
              style={{
                flex: 1,
                height: cardHeight * 0.15,
                backgroundColor: "#161619",
                borderRadius: 999,
                position: "relative",
                overflow: "hidden", // Important for masking the bar
                boxShadow: "inset 0 2px 4px rgba(0,0,0,0.5)"
              }}
            >
              {/* Animated Green Bar */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  bottom: 0,
                  width: `${currentProgress}%`,
                  background: `linear-gradient(90deg, ${primaryColor}44 0%, ${primaryColor} 100%)`,
                  borderRadius: 999,
                  boxShadow: `0 0 30px ${primaryColor}88`,
                }}
              />
              
              {/* Plane Icon (Moves with bar) */}
              <div
                style={{
                  position: "absolute",
                  left: `${currentProgress}%`,
                  top: "50%",
                  transform: "translate(-50%, -50%) rotate(90deg)",
                  zIndex: 2,
                  marginLeft: -4 // Slight visual adjustment
                }}
              >
                <PlaneIcon color="white" size={cardHeight * 0.08} />
              </div>

              {/* Shine effect on bar */}
              <div 
                style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    height: "50%",
                    background: "linear-gradient(180deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0) 100%)",
                    borderRadius: "999px 999px 0 0",
                    pointerEvents: "none"
                }}
              />
            </div>

            {/* Remaining Time */}
            <div 
                style={{ 
                    fontFamily: "Roboto Mono, monospace",
                    color: "#555",
                    fontSize: cardWidth * 0.02,
                    fontWeight: 500,
                    minWidth: cardWidth * 0.1,
                    textAlign: "right"
                }}
            >
                -2H 48M
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FlightTrackerCard;